cd <run-dir>; sqlite3 -header warehouse.db "
-- Q1
select g.region, round(sum(p.premium_amt - p.cancellation_amt),2) nwp, round(sum(p.premium_amt),2) net_before_canc from fct_policy_premium p join dim_geography g using(geo_id) where p.status in ('written','cancelled') and p.eff_dt between '2026-07-01' and '2026-09-30' group by 1;
-- Q2
select d.product_line, round(sum(p.premium_amt_gross),2) gwp from fct_policy_premium p join dim_product d using(product_id) where p.status in ('written','cancelled') and p.eff_dt between '2026-01-01' and '2026-06-30' group by 1;
